package org.slavicmyths.morozko;
import java.util.UUID;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.projectile.ThrowableProjectile;
import net.minecraft.world.phys.*;
import net.minecraft.nbt.CompoundTag;
public final class FrostShard extends ThrowableProjectile {
 public UUID session;private float damage;private int cold;private boolean winterWeapon;private UUID silenceCast;
 public boolean winterWeapon(){return winterWeapon;}
 private static boolean winter(LivingEntity e){return e instanceof net.minecraft.server.level.ServerPlayer p&&org.slavicmyths.winter.WinterAccessories.winterItem(p.getMainHandItem());}
 public static void launchSilenceBlade(net.minecraft.server.level.ServerPlayer p,float yawOffset,UUID cast){var e=FrostContent.SHARD.get().create(p.level());if(e==null)return;e.setOwner(p);e.damage=9;e.winterWeapon=true;e.silenceCast=cast;var direction=Vec3.directionFromRotation(p.getXRot(),p.getYRot()+yawOffset);e.setPos(p.getEyePosition().add(direction.scale(.8)));e.shoot(direction.x,direction.y,direction.z,1,0);p.level().addFreshEntity(e);}
 public FrostShard(EntityType<? extends FrostShard> t,net.minecraft.world.level.Level w){super(t,w);}
 @Override protected void defineSynchedData(net.minecraft.network.syncher.SynchedEntityData.Builder b){}
 @Override protected double getDefaultGravity(){return 0;}
 public static void launch(LivingEntity owner,Vec3 target,float damage,int cold,UUID session){var e=FrostContent.SHARD.get().create(owner.level());if(e==null)return;e.setOwner(owner);e.session=session;e.winterWeapon=winter(owner);e.damage=damage;e.cold=cold;if(owner instanceof Morozko){double yaw=Math.toRadians(owner.getYRot());var side=new Vec3(Math.cos(yaw)*.875,0,Math.sin(yaw)*.875);e.setPos(owner.position().add(side).add(0,2.17,0).add(owner.getLookAngle().multiply(1,0,1).normalize().scale(1)));}else e.setPos(owner.getEyePosition().add(owner.getLookAngle().scale(.8)));var d=target.subtract(e.position()).normalize();e.shoot(d.x,d.y,d.z,1,0);owner.level().addFreshEntity(e);}
 public static void launchAt(LivingEntity owner,Vec3 origin,Vec3 target,float damage,int cold){var e=FrostContent.SHARD.get().create(owner.level());if(e==null)return;e.setOwner(owner);e.winterWeapon=winter(owner);e.damage=damage;e.cold=cold;e.setPos(origin);var d=target.subtract(origin).normalize();e.shoot(d.x,d.y,d.z,1,0);owner.level().addFreshEntity(e);}
 @Override protected boolean canHitEntity(Entity e){if(!(e instanceof LivingEntity l)||!(getOwner() instanceof LivingEntity from))return false;if(winterWeapon&&from instanceof net.minecraft.server.level.ServerPlayer p)return org.slavicmyths.combat.CombatTargeting.canAttack(p,l,org.slavicmyths.combat.CombatTargeting.Context.PROJECTILE)&&super.canHitEntity(e);return (from instanceof org.slavicmyths.icequeen.IceQueen q?l instanceof net.minecraft.world.entity.player.Player p&&q.active()&&q.participant(p):from instanceof org.slavicmyths.icequeen.QueenMinion m?m.canHitTrial(l):from instanceof Morozko b?b.candidate(l):from instanceof net.minecraft.server.level.ServerPlayer?FrostStaffTargeting.canHit(l,from):FrostWorld.hostile(l,from))&&super.canHitEntity(e);}
 @Override protected void onHitEntity(EntityHitResult h){if(level().isClientSide||!(h.getEntity() instanceof LivingEntity t)||!(getOwner() instanceof LivingEntity from))return;if(t.hurt(FrostDamage.projectile(silenceCast!=null?"winter_silence_blade":"morozko_frost",this,from),damage)){if(cold>0)FrostCold.add(t,cold);if(silenceCast!=null&&from instanceof net.minecraft.server.level.ServerPlayer p)org.slavicmyths.winter.WinterLegendItem.bladeHit(p,t,silenceCast);if(from instanceof Morozko b)b.attacked(t);if(from instanceof net.minecraft.server.level.ServerPlayer p)FrostSkills.remember(p,t);}}
 @Override protected void onHit(HitResult h){super.onHit(h);if(!level().isClientSide){FrostContent.sound(this,"spike_break");discard();}}
 @Override public void tick(){super.tick();if(level().isClientSide)level().addParticle(net.minecraft.core.particles.ParticleTypes.SNOWFLAKE,getX(),getY(),getZ(),0,0,0);else if(tickCount>24||getOwner()==null||getOwner() instanceof org.slavicmyths.icequeen.IceQueen q&&!q.active()||getOwner() instanceof org.slavicmyths.icequeen.QueenMinion m&&!m.trialActive()||session!=null&&(!(getOwner() instanceof Morozko b)||!b.fighting()||position().distanceToSqr(b.anchor)>1600))discard();}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);discard();}
}
